import java.util.*;

public class Solution {
    // Prova por troca: o que termina primeiro deixa o maior espaço livre para o resto.
    static int maximo(int[][] intervalos) {
        int[][] a = intervalos.clone();
        Arrays.sort(a, Comparator.comparingInt(x -> x[1]));
        int total = 0;
        long fim = Long.MIN_VALUE;
        for (int[] x : a) {
            if (x[0] >= fim) {
                total++;
                fim = x[1];
            }
        }
        return total;
    }
}

