import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static int bruta(int[][] a) {
        int melhor = 0;
        for (int m = 0; m < 1 << a.length; m++) {
            boolean ok = true;
            for (int i = 0; i < a.length && ok; i++) for (int j = i + 1; j < a.length && ok; j++)
                if ((m >> i & 1) == 1 && (m >> j & 1) == 1 && a[i][0] < a[j][1] && a[j][0] < a[i][1]) ok = false;
            if (ok) melhor = Math.max(melhor, Integer.bitCount(m));
        }
        return melhor;
    }

    @Test void exemplos() {
        assertEquals(3, Solution.maximo(new int[][]{{1, 2}, {2, 3}, {3, 4}, {1, 3}}));
        assertEquals(2, Solution.maximo(new int[][]{{1, 100}, {2, 3}, {50, 60}}));
        assertEquals(0, Solution.maximo(new int[][]{}));
    }

    @Test void comecarCedoNaoEhOCriterio() {
        assertEquals(2, Solution.maximo(new int[][]{{0, 10}, {1, 2}, {3, 4}}));
    }

    @Test void extremos() {
        assertEquals(2, Solution.maximo(new int[][]{{Integer.MIN_VALUE, 0}, {0, Integer.MAX_VALUE}}));
    }

    @Test void aleatorioContraBruta() {
        var rnd = new Random(5);
        for (int t = 0; t < 300; t++) {
            int[][] a = new int[rnd.nextInt(11)][];
            for (int i = 0; i < a.length; i++) {
                int s = rnd.nextInt(20);
                a[i] = new int[]{s, s + 1 + rnd.nextInt(6)};
            }
            assertEquals(bruta(a), Solution.maximo(a));
        }
    }
}

