public class Solution {
    static int inicio(int[] gas, int[] custo) {
        long total = 0, tanque = 0;
        int partida = 0;
        for (int i = 0; i < gas.length; i++) {
            long saldo = (long) gas[i] - custo[i];
            total += saldo;
            tanque += saldo;
            if (tanque < 0) { // ninguém em [partida, i] serve: recomeça depois de i
                partida = i + 1;
                tanque = 0;
            }
        }
        return total >= 0 ? partida : -1;
    }
}

