import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static boolean funciona(int[] g, int[] c, int s) {
        long t = 0;
        for (int k = 0; k < g.length; k++) {
            t += g[(s + k) % g.length] - c[(s + k) % g.length];
            if (t < 0) return false;
        }
        return true;
    }

    @Test void exemplos() {
        assertEquals(3, Solution.inicio(new int[]{1, 2, 3, 4, 5}, new int[]{3, 4, 5, 1, 2}));
        assertEquals(-1, Solution.inicio(new int[]{2, 3, 4}, new int[]{3, 4, 3}));
        assertEquals(0, Solution.inicio(new int[]{5}, new int[]{5}));
    }

    @Test void aleatorioContraBruta() {
        var rnd = new Random(6);
        for (int t = 0; t < 500; t++) {
            int n = 1 + rnd.nextInt(8);
            int[] g = rnd.ints(n, 0, 6).toArray(), c = rnd.ints(n, 0, 6).toArray();
            boolean existe = false;
            for (int s = 0; s < n; s++) existe |= funciona(g, c, s);
            int r = Solution.inicio(g, c);
            if (!existe) assertEquals(-1, r, Arrays.toString(g) + Arrays.toString(c));
            else assertTrue(r >= 0 && r < n && funciona(g, c, r), Arrays.toString(g) + Arrays.toString(c) + " -> " + r);
        }
    }
}
